import{_ as i,l as o,o as e,c as l,v as t,p as s,x as n,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"生成函数","description":"","frontmatter":{"title":"生成函数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/generating-functions.md","filePath":"cs/generating-functions.md","lastUpdated":1789023840000}'),p={name:"cs/generating-functions.md"};function _(u,a,m,f,T,x){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="生成函数" tabindex="-1">生成函数 <a class="header-anchor" href="#生成函数" aria-label="Permalink to &quot;生成函数&quot;">​</a></h1><div class="epigraph"><p>数列 $\\{a_n\\}$ 收成 $\\sum a_n x^n$；卷积变乘法，线性递推变有理函数，计数变成多项式运算。</p><footer>—— 据 Wilf, generatingfunctionology；Knuth TAOCP 卷 1；Flajolet and Sedgewick, Analytic Combinatorics 整理</footer></div><p>上一课<a href="/cs/lucas-theorem">Lucas 定理</a>给了模 \\(p\\) 的 \\(\\binom n m\\)。普通生成函数（OGF）在形式幂级数里把卷积当乘。缺口是这套<strong>字典</strong>：加法、乘、复合，以及 \\(1/(1-x)\\)、\\(\\exp\\) 的指数生成函数（EGF）点名。不重写 NTT 实现。后课莫比乌斯反演是数论卷积，可视为狄利克雷生成函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OGF：\\(A(x)=\\sum a_n x^n\\)。两独立选取的方案卷积 \\(\\Leftrightarrow A(x)B(x)\\)。Catalan、划分、背包个数都是乘与 \\([x^n]\\)。EGF：\\(\\sum a_n x^n/n!\\) 适合标记组合、集合、排列。线性递推 \\(\\Leftrightarrow\\) 有理生成函数，部分分式给通项。</p><p>缺口是翻译，不是把 FFT 再讲一遍。提取 \\([x^n]\\) 用 NTT 乘或牛顿（上一单元）。</p><h3 id="形式幂级数不是分析课" tabindex="-1">形式幂级数不是分析课 <a class="header-anchor" href="#形式幂级数不是分析课" aria-label="Permalink to &quot;形式幂级数不是分析课&quot;">​</a></h3><p>半径、奇点分析（Flajolet）给渐近，本课点名。算法课先当多项式截断。不要一上来留数。</p><p><span class="marginnote">Wilf 的书是组合生成函数入门。Knuth 用生成函数分析算法。后课 \\(\\mu\\) 反演是另一卷积（除数格）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列状态或组合分解，写出 \\(A(x)\\) 方程，解或牛顿求系数。需要前 \\(n\\) 项则截断乘。模素数时全程 NTT。</p>',11)),(e(),s(h,null,{default:n(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E6%95%B0%E5%88%97%20a_n%22%5D%20--%3E%20OGF%5B%22OGF%20%E5%8D%B7%E7%A7%AF%3D%E4%B9%98%22%5D%0A%20%20SEQ%20--%3E%20EGF%5B%22EGF%20%E6%A0%87%E8%AE%B0%E7%BB%84%E5%90%88%22%5D%0A%20%20OGF%20--%3E%20COEF%5B%22%5Bx%5En%5D%20NTT%2F%E7%89%9B%E9%A1%BF%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>背包：\\(\\prod(1+x^{w_i})\\) 或无限 \\(\\prod 1/(1-x^{w_i})\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卷积定理在形式级数是定义。线性递推的特征多项式与分母相同。与矩阵幂：有理 OGF 的系数仍可用伴生矩阵，两套语言。与 DP：生成函数是批量 DP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写奇点分析全文。不写对称函数。后课默认：卷积计数优先生成函数 + NTT。下一课莫比乌斯反演。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OGF 乘 = 卷积；EGF 管标记。</li><li>线性递推 \\(\\leftrightarrow\\) 有理函数。</li><li>系数用已有多项式算法。</li><li>出处：Wilf；Knuth TAOCP；Flajolet–Sedgewick。</li></ul>',7))])}const F=i(p,[["render",_]]);export{g as __pageData,F as default};
